-- Check: sample records per register (10 each).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-9001-000000000032'::uuid, '00000000-0000-4000-9001-000000000033'::uuid, '00000000-0000-4000-9001-000000000034'::uuid, '00000000-0000-4000-9001-000000000035'::uuid, '00000000-0000-4000-9001-000000000036'::uuid, '00000000-0000-4000-9001-000000000037'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
